# Desk latest: retain useful existing verified stories, correct geography, dedupe by source URL, prepend today's
p=D/'desk-latest.json'; old=json.loads(p.read_text()) if p.exists() else {'desks':{}}
floors={'world':4,'asia':5,'hong-kong':5,'japan':5,'market-economy':5,'ai-tech':4,'manga-anime':3,'manchester-united':3,'football':6}
newdesks={}
for slug,minimum in floors.items():
    candidates=[]
    for x in S+extra:
        if slug in x.get('deskSlugs',[]) or x.get('desk')==slug:
            y=dict(x); y['status']='LATEST'; candidates.append(y)
    for x in old.get('desks',{}).get(slug,[]):
        text=' '.join(str(x.get(k,'')) for k in ['title','section'])
        if slug=='world' and re.search(r'伊朗|中東|霍爾木茲|以色列|Middle East|West Asia',text,re.I): continue
        candidates.append(x)
    seen=set(); out=[]
    for x in candidates:
        key=x.get('sourceUrl') or x.get('id')
        if key in seen: continue
        seen.add(key); out.append(x)
    newdesks[slug]=out[:max(minimum,8)]
    if len(newdesks[slug])<minimum: raise RuntimeError(f'desk depth {slug} {len(newdesks[slug])}<{minimum}')
desk={'date':DATE,'generatedAt':NOW,'mode':'ROLLING_DESK_LATEST','editorialStandardVersion':3,'contentVersion':3,'desks':newdesks}

